(function() {
  const canvas = document.getElementById('search-canvas');
  const ctx = canvas.getContext('2d');

  // State
  let currentStep = 0;
  const maxSteps = 3;

  // Simulation Data (Teaching Values)
  // Simulating a search space of 0 to 360 degrees
  const totalRange = 360;
  const initialCandidates = 18; // Traditional dense grid
  const adaptiveCandidates = 6; // Adaptive sparse grid

  // Mock history of "Best Index" found in previous iterations
  // Step 0: Initial broad search
  // Step 1: Found best at index 12 (approx 240 deg)
  // Step 2: Refined around 240, found best at local index 3
  // Step 3: Final convergence
  const iterationHistory = [
    { range: [0, 360], bestIdx: 12, width: 360 },
    { range: [200, 280], bestIdx: 3, width: 80 },
    { range: [230, 250], bestIdx: 2, width: 20 },
    { range: [238, 242], bestIdx: 3, width: 4 }
  ];

  const stepsInfo = [
    { title: "步骤 1：获取上一轮最佳索引", desc: "读取第 k-1 次迭代计算出的最佳角度索引。" },
    { title: "步骤 2：确定新搜索边界", desc: "根据索引位置计算新的搜索区间边界 [start, end]。" },
    { title: "步骤 3：生成局部候选点", desc: "在确定的新区间内，均匀生成 qaz 个候选角度值。" }
  ];

  // UI Elements
  const statIter = document.getElementById('stat-iter');
  const statQ = document.getElementById('stat-q');
  const statWidth = document.getElementById('stat-width');
  const stepTitle = document.getElementById('step-title');
  const btnNext = document.getElementById('btn-next');
  const btnPrev = document.getElementById('btn-prev');
  const btnReset = document.getElementById('btn-reset');

  function draw() {
    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const w = canvas.width;
    const h = canvas.height;
    const padding = 40;
    const drawWidth = w - padding * 2;

    const data = iterationHistory[currentStep];
    const isInitial = currentStep === 0;

    // Draw Axis
    ctx.beginPath();
    ctx.moveTo(padding, h - padding);
    ctx.lineTo(w - padding, h - padding);
    ctx.strokeStyle = '#2C3E50';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Labels
    ctx.fillStyle = '#7F8C8D';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('0°', padding, h - padding + 20);
    ctx.fillText('360°', w - padding, h - padding + 20);
    ctx.fillText('角度搜索空间 (Azimuth AoD)', w / 2, h - 10);

    // Draw Full Range Background (Faded)
    ctx.fillStyle = 'rgba(44, 62, 80, 0.05)';
    ctx.fillRect(padding, 50, drawWidth, h - padding - 50);

    // Calculate positions
    const startX = padding + (data.range[0] / totalRange) * drawWidth;
    const endX = padding + (data.range[1] / totalRange) * drawWidth;
    const rangeWidth = endX - startX;

    // Draw Active Search Interval
    ctx.fillStyle = 'rgba(0, 184, 148, 0.1)'; // Accent color low opacity
    ctx.fillRect(startX, 50, rangeWidth, h - padding - 50);

    ctx.strokeStyle = '#00B894';
    ctx.lineWidth = 2;
    ctx.strokeRect(startX, 50, rangeWidth, h - padding - 50);

    // Draw Candidates
    const count = isInitial ? initialCandidates : adaptiveCandidates;
    const stepX = rangeWidth / (count - 1);

    for (let i = 0; i < count; i++) {
      const x = startX + i * stepX;

      // Line
      ctx.beginPath();
      ctx.moveTo(x, 50);
      ctx.lineTo(x, h - padding);
      ctx.strokeStyle = i === data.bestIdx ? '#E17055' : '#2C3E50'; // Warm color for best
      ctx.lineWidth = i === data.bestIdx ? 3 : 1;
      ctx.setLineDash(i === data.bestIdx ? [] : [5, 5]);
      ctx.stroke();
      ctx.setLineDash([]);

      // Dot
      ctx.beginPath();
      ctx.arc(x, h - padding, 4, 0, Math.PI * 2);
      ctx.fillStyle = i === data.bestIdx ? '#E17055' : '#2C3E50';
      ctx.fill();

      // Highlight Best Index Label
      if (i === data.bestIdx) {
        ctx.fillStyle = '#E17055';
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText('最佳索引 (ι)', x, 40);
      }
    }

    // Update Stats
    statIter.textContent = isInitial ? '初始' : currentStep;
    statQ.textContent = count;
    statWidth.textContent = Math.round(data.width) + '°';

    // Update Step Text
    if (currentStep > 0) {
      stepTitle.textContent = stepsInfo[currentStep - 1].title;
    } else {
      stepTitle.textContent = "初始状态：全空间稀疏采样";
    }
  }

  function nextStep() {
    if (currentStep < maxSteps) {
      currentStep++;
      draw();
    }
  }

  function prevStep() {
    if (currentStep > 0) {
      currentStep--;
      draw();
    }
  }

  function reset() {
    currentStep = 0;
    draw();
  }

  // Event Listeners
  btnNext.addEventListener('click', nextStep);
  btnPrev.addEventListener('click', prevStep);
  btnReset.addEventListener('click', reset);

  // Keyboard Support
  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') nextStep();
    if (e.key === 'ArrowLeft') prevStep();
  });

  // Initial Draw
  draw();
})();
